import { focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const footer = tv({
  slots: {
    root: "w-full border-t-3 border-border bg-raised",
    inner: "mx-auto flex w-full max-w-7xl flex-col gap-10 px-4 py-12 sm:px-6",
    brand: "flex flex-col gap-3",
    mark: "font-display text-2xl font-black tracking-tight uppercase text-foreground",
    blurb: "max-w-xs text-pretty text-sm text-foreground",
    columns: "grid flex-1 gap-8 sm:grid-cols-2 lg:grid-cols-4",
    column: "flex flex-col gap-3",
    columnTitle: "font-mono text-xs font-bold tracking-widest uppercase",
    list: "flex flex-col gap-2",
    link: ["flex min-h-11 items-center text-foreground hover:underline", focusRing],
    bottom:
      "flex flex-col gap-3 border-t-3 border-border pt-6 sm:flex-row sm:items-center sm:justify-between",
    note: "font-mono text-xs font-bold",
    social: "flex items-center gap-3",
  },
  variants: {
    variant: {
      simple: { inner: "gap-8" },
      columns: { inner: "gap-10 lg:flex-row lg:justify-between" },
    },
  },
  defaultVariants: {
    variant: "columns",
  },
});

export type FooterVariants = VariantProps<typeof footer>;

import { footer, type FooterVariants } from "@/lib/beton/recipes/footer.recipe";
import type { ComponentProps, ReactNode } from "react";

export interface FooterLink {
  label: ReactNode;
  href: string;
}

export interface FooterColumn {
  /** What the group of links is called. */
  title: ReactNode;
  links: FooterLink[];
}

export interface FooterProps extends ComponentProps<"footer">, FooterVariants {
  /** The name of the thing. */
  mark?: ReactNode;
  /** A line about what it is. */
  blurb?: ReactNode;
  /** Groups of links. */
  columns?: FooterColumn[];
  /** The line along the bottom: a licence, a copyright. */
  note?: ReactNode;
  /** Links to wherever you are: GitHub, elsewhere. */
  social?: ReactNode;
}

/** The end of the page: who made it, where everything is, and the licence. */
export function Footer({
  variant = "columns",
  mark,
  blurb,
  columns = [],
  note,
  social,
  className,
  children,
  ...props
}: FooterProps) {
  const styles = footer({ variant });
  return (
    <footer {...props} className={styles.root({ class: className })}>
      <div className={styles.inner()}>
        {mark || blurb ? (
          <div className={styles.brand()}>
            {mark ? <p className={styles.mark()}>{mark}</p> : null}
            {blurb ? <p className={styles.blurb()}>{blurb}</p> : null}
          </div>
        ) : null}
        {columns.length ? (
          <div className={styles.columns()}>
            {columns.map((column, index) => (
              <nav
                key={index}
                aria-label={typeof column.title === "string" ? column.title : undefined}
                className={styles.column()}
              >
                <p className={styles.columnTitle()}>{column.title}</p>
                <ul className={styles.list()}>
                  {column.links.map((link) => (
                    <li key={link.href}>
                      <a href={link.href} className={styles.link()}>
                        {link.label}
                      </a>
                    </li>
                  ))}
                </ul>
              </nav>
            ))}
          </div>
        ) : null}
        {children}
      </div>
      {note || social ? (
        <div className={styles.inner()}>
          <div className={styles.bottom()}>
            {note ? <p className={styles.note()}>{note}</p> : null}
            {social ? <div className={styles.social()}>{social}</div> : null}
          </div>
        </div>
      ) : null}
    </footer>
  );
}
